INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 12, 'theory', 'Quiz: list and vector');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 0, 'What happens if you remove elements from a vector inside for x in &v?', '["the program will not build: the vector is already borrowed by the loop", "it works, as in Python", "elements get skipped", "a panic at run time"]', 0, 'The compiler forbids changing a vector while it is being iterated. Use retain, drain, or build a new vector.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 1, 'What replaces Python''s l.pop(i)?', '["v.pop(i)", "v.delete(i)", "v.remove(i) — returns the removed element", "v.take(i)"]', 2, 'A vector has pop() with no arguments too, but it returns an Option; pop(i) is remove(i).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 2, 'How does the Python slice l[1:3] differ from &v[1..3] in Rust?', '["no difference", "both are references to part of the list", "in Rust a slice copies, in Python it does not", "in Python a slice is a copy, in Rust it is a reference to part of the vector"]', 3, 'A Rust slice does not copy data: nothing is allocated or copied.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 3, 'How do you make an independent copy of a vector in Rust, including nested elements?', '["let b = a;", "a.clone()", "let b = &a;", "a.copy()"]', 1, 'clone makes a deep copy; assignment moves ownership.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 12, 4, 'Which type suits a queue with fast appending at the end and taking from the front?', '["Vec", "VecDeque", "[T; N]", "BinaryHeap"]', 1, 'VecDeque is the analog of collections.deque. Taking from the front of a Vec costs linear time.');
